WHERE id = 'f1c2b35a-e186-4096-8ac2-ebe55791cc04'::uuid;

UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Mengapa penting memeriksa izin OJK sebelum berinvestasi?", "options": ["Agar return lebih tinggi", "Produk berizin lebih aman dan dilindungi; produk tidak berizin ilegal", "OJK menjamin keuntungan", "Karena semua produk tanpa izin pasti menguntungkan"], "answer": "Produk berizin lebih aman dan dilindungi; produk tidak berizin ilegal", "explanation": "OJK mengawasi produk keuangan berizin; produk di luar daftar tidak memiliki perlindungan."}, {"type": "true_false", "question": "Jika produk tidak terdaftar di situs OJK, uangmu masih tetap aman karena perusahaan pasti jujur.", "answer": false, "explanation": "Produk tidak berizin tidak punya perlindungan jika terjadi masalah."}, {"type": "fill_blank", "question": "OJK adalah singkatan dari Otoritas ____ Keuangan.", "answer": "Jasa", "explanation": "OJK mengawasi lembaga jasa keuangan di Indonesia."}]'::jsonb
WHERE id = 'c2349ee3-966a-4bb5-92ad-6aa7e604d2a3'::uuid;

UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa tujuan utama serangan phishing?", "options": ["Memberikan hadiah gratis", "Mencuri data pribadi, password, atau OTP", "Meningkatkan literasi keuangan", "Menawarkan pekerjaan"], "answer": "Mencuri data pribadi, password, atau OTP", "explanation": "Phishing memaksa atau menipu korban agar memberikan informasi sensitif."}, {"type": "true_false", "question": "Bank resmi akan meminta OTP-mu melalui telepon atau chat untuk keamanan akun.", "answer": false, "explanation": "Bank dan regulator resmi tidak meminta password atau OTP."}, {"type": "fill_blank", "question": "Social engineering memanipulasi orang secara ____ untuk mendapatkan informasi atau uang.", "answer": "emosional", "explanation": "Penipu sering memanfaatkan rasa takut, terburu-buru, atau percaya untuk menipu korban."}]'::jsonb
