UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa perbedaan utama bisnis MLM sah dan skema piramida?", "options": ["MLM sah menghasilkan uang dari penjualan produk; piramida dari perekrutan", "Tidak ada perbedaan", "Piramida selalu legal", "MLM sah tidak menjual produk"], "answer": "MLM sah menghasilkan uang dari penjualan produk; piramida dari perekrutan", "explanation": "Fokus pada perekrutan daripada penjualan produk adalah tanda piramida."}, {"type": "true_false", "question": "Skema piramida bisa bertahan selamanya selama terus ada anggota baru.", "answer": false, "explanation": "Piramida akan runtuh ketika perekrutan melambat karena tidak cukup orang baru."}, {"type": "fill_blank", "question": "Bisnis sah menghasilkan uang dari ____ nyata, bukan hanya dari biaya perekrutan.", "answer": "pelanggan", "explanation": "Jika penghasilan utama berasal dari perekrutan, itu bukan bisnis nyata."}]'::jsonb
