UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Mengapa bunga majemuk bisa tumbuh lebih cepat dari bunga sederhana?", "options": ["Karena menghitung bunga dari bunga sebelumnya", "Karena tidak ada risiko", "Karena bank menambahkan uang gratis", "Karena pajak lebih kecil"], "answer": "Karena menghitung bunga dari bunga sebelumnya", "explanation": "Bunga majemuk menghasilkan bunga dari pokok dan bunga yang sudah terkumpul."}, {"type": "true_false", "question": "Dua faktor paling penting dalam bunga majemuk adalah waktu dan suku bunga.", "answer": true, "explanation": "Semakin lama waktu dan semakin tinggi suku bunga, efek salju bunga majemuk semakin besar."}, {"type": "fill_blank", "question": "Bunga majemuk menciptakan efek ____ yang membuat uang tumbuh semakin cepat dari waktu ke waktu.", "answer": "salju", "explanation": "Seperti bola salju, bunga majemuk semakin membesar seiring berjalannya waktu."}]'::jsonb
