UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Kapan uang sebaiknya disimpan di bank daripada diinvestasikan?", "options": ["Untuk dana darurat dan kebutuhan jangka pendek", "Untuk tujuan pensiun 30 tahun lagi", "Saat ingin return setinggi mungkin", "Saat tidak peduli dengan keamanan"], "answer": "Untuk dana darurat dan kebutuhan jangka pendek", "explanation": "Bank cocok untuk uang yang harus aman dan mudah diakses."}, {"type": "true_false", "question": "Investasi selalu lebih baik daripada menyimpan uang di bank.", "answer": false, "explanation": "Investasi punya risiko dan cocok untuk uang jangka panjang, bukan semua kebutuhan."}, {"type": "fill_blank", "question": "Bank melindungi uang jangka pendek; investasi berpotensi menumbuhkan uang ____.", "answer": "jangka panjang", "explanation": "Investasi untuk tujuan yang masih jauh, dengan risiko yang bisa ditoleransi."}]'::jsonb
