UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa hubungan umum antara risiko dan return?", "options": ["Return tinggi selalu tanpa risiko", "Potensi return tinggi biasanya berarti risiko tinggi", "Risiko tinggi selalu menghasilkan return tinggi", "Tidak ada hubungan"], "answer": "Potensi return tinggi biasanya berarti risiko tinggi", "explanation": "Risiko dan return berjalan berdampingan; tidak ada makan siang gratis."}, {"type": "true_false", "question": "Tidak ada cara aman untuk mendapatkan return besar dengan cepat.", "answer": true, "explanation": "Return besar dengan cepat selalu disertai risiko besar atau kemungkinan penipuan."}, {"type": "fill_blank", "question": "Trade-off antara risiko dan return berarti kamu tidak bisa mendapatkan return tinggi tanpa menerima ____ lebih tinggi.", "answer": "risiko", "explanation": "Return dan risiko biasanya saling terkait."}]'::jsonb
WHERE id = 'e81a8f71-77ab-44ca-b48f-a0e985313e33'::uuid;

UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Mengapa diversifikasi penting?", "options": ["Menjamin return tertinggi", "Mengurangi dampak jika satu investasi turun", "Menghilangkan semua risiko", "Memusatkan semua uang di satu saham"], "answer": "Mengurangi dampak jika satu investasi turun", "explanation": "Diversifikasi menyebarkan risiko sehingga kerugian satu aset tidak menghancurkan semuanya."}, {"type": "true_false", "question": "Menaruh semua uang di satu saham adalah contoh diversifikasi yang baik.", "answer": false, "explanation": "Diversifikasi berarti menyebarkan investasi, bukan memusatkannya."}, {"type": "fill_blank", "question": "Diversifikasi berarti tidak menaruh semua telur dalam satu ____.", "answer": "keranjang", "explanation": "Peribahasa ini menggambarkan pentingnya menyebarkan risiko."}]'::jsonb
WHERE id = '4666fa33-6865-43ae-824e-dd0d9a5d1ac2'::uuid;

UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa itu reksa dana?", "options": ["Pinjaman dari bank", "Dana yang dipool dari banyak investor dan dikelola manajer investasi", "Tabungan dengan bunga tetap", "Asuransi jiwa"], "answer": "Dana yang dipool dari banyak investor dan dikelola manajer investasi", "explanation": "Reksa dana mengumpulkan uang banyak orang untuk diinvestasikan secara kolektif."}, {"type": "true_false", "question": "Semua reksa dana memiliki risiko dan return yang sama.", "answer": false, "explanation": "Jenis reksa dana berbeda-beda, mulai dari pasar uang yang relatif aman hingga saham yang lebih berisiko."}, {"type": "fill_blank", "question": "Reksa dana memungkinkan investor kecil memiliki ____ portofolio yang dikelola profesional.", "answer": "bagian", "explanation": "Dengan reksa dana, kamu membeli unit yang mewakili bagian dari portofolio besar."}]'::jsonb
