UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa yang dimaksud dengan saham?", "options": ["Pinjaman kepada perusahaan", "Bagian kepemilikan dalam perusahaan", "Tabungan di bank", "Polis asuransi"], "answer": "Bagian kepemilikan dalam perusahaan", "explanation": "Membeli saham berarti memiliki sebagian kecil dari perusahaan tersebut."}, {"type": "true_false", "question": "Membeli saham berarti kamu menjadi salah satu pemilik perusahaan, meski bagiannya kecil.", "answer": true, "explanation": "Saham mewakili kepemilikan, sehingga pemegang saham berbagi risiko dan potensi keuntungan."}, {"type": "fill_blank", "question": "Saham memberi potensi keuntungan, tetapi juga berisiko ____ jika perusahaan performanya buruk.", "answer": "rugi", "explanation": "Sebagai pemilik, kamu bisa untung atau rugi tergantung kinerja perusahaan."}]'::jsonb
