UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa yang dimaksud dengan portfolio thinking?", "options": ["Membeli satu saham saja", "Melihat keseluruhan aset dan bagaimana campurannya sesuai tujuan", "Menghindari semua investasi", "Fokus pada satu jenis aset"], "answer": "Melihat keseluruhan aset dan bagaimana campurannya sesuai tujuan", "explanation": "Portfolio thinking berarti menilai kombinasi seluruh kepemilikan, bukan satu aset sendiri."}, {"type": "true_false", "question": "Saham yang berisiko jika dimiliki sendiri bisa menjadi bagian yang wajar dalam portofolio yang lebih besar.", "answer": true, "explanation": "Risiko satu aset bisa diredam ketika menjadi bagian kecil dari portofolio terdiversifikasi."}, {"type": "fill_blank", "question": "Portofolio adalah kombinasi dari semua ____ finansial yang kamu miliki.", "answer": "aset", "explanation": "Portofolio mencakup tabungan, saham, reksa dana, dan aset lainnya."}]'::jsonb
WHERE id = '969d9364-8111-4f93-a048-c4a60218bc34'::uuid;

UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Mengapa return setelah pajak penting?", "options": ["Karena pajak selalu nol", "Karena pajak bisa mengurangi jumlah uang yang benar-benar kamu terima", "Karena pajak meningkatkan return", "Karena pajak tidak berlaku untuk investasi"], "answer": "Karena pajak bisa mengurangi jumlah uang yang benar-benar kamu terima", "explanation": "Return kotor bisa lebih besar dari return bersih yang kamu simpan setelah pajak."}, {"type": "true_false", "question": "Semua jenis return investasi di Indonesia bebas pajak.", "answer": false, "explanation": "Berbagai jenis return, seperti bunga deposito dan dividen, bisa dikenakan pajak."}, {"type": "fill_blank", "question": "Return yang tersisa setelah dipotong pajas disebut ____ return.", "answer": "bersih", "explanation": "Net return adalah return yang benar-benar kamu dapat setelah pajak dan biaya."}]'::jsonb
