UPDATE public.lessons
SET quiz_data_id = '[{"type": "multiple_choice", "question": "Apa langkah pertama dalam membangun rencana keuangan untuk kebanyakan anak muda Indonesia?", "options": ["Membeli saham sebanyak-banyaknya", "Menutupi kebutuhan dasar, membangun dana darurat, dan melunasi utang berbunga tinggi", "Membeli properti segera", "Mengabaikan asuransi kesehatan"], "answer": "Menutupi kebutuhan dasar, membangun dana darurat, dan melunasi utang berbunga tinggi", "explanation": "Fondasi keuangan yang kuat dimulai dari kebutuhan dasar, dana darurat, dan utang tinggi."}, {"type": "true_false", "question": "Rencana keuangan yang baik mencakup tujuan, dana darurat, utang, perlindungan, dan investasi.", "answer": true, "explanation": "Rencana keuangan menyatukan semua aspek keuangan dalam urutan yang masuk akal."}, {"type": "fill_blank", "question": "Sebelum berinvestasi agresif, pastikan kamu sudah punya dana ____ dan perlindungan kesehatan.", "answer": "darurat", "explanation": "Dana darurat dan perlindungan dasar harus didahulukan sebelum mengambil risiko investasi."}]'::jsonb
